drop TABLE account_holder_detailes
create table BANK(BANK_ID NUMnullBER(5)PRIMARY KEY,B_NAME VARCHAR(10),B_HEADQ VARCHAR(10),B_PINCODE NUMBER(6),B_MAILID VARCHAR(50),B_CONTACT_NO NUMBER(10));
create  table BRANCH(BRANCH_ID NUMBER(5)PRIMARY KEY,B_NAME VARCHAR(10),B_IFSC_CODE VARCHAR(12),B_ADDRESS VARCHAR(20),B_PINCODE NUMBER(6),B_CONTACT_NO NUMBER(10),B_MAILID VARCHAR(50),BANK_ID NUMBER(5),FOREIGN KEY(BANK_ID)REFERENCES BANK(BANK_ID));
create table EMPLOYEE(EMPLOYEE_ID NUMBER(5),E_NAME VARCHAR(10),DESIGNATION VARCHAR(10),SALARY NUMBER(10),JION_DATE DATE,CONTACT_NO NUMBER(10),DEPARTMENT_ID NUMBER(5),BRANCH_ID NUMBER(5),FOREIGN KEY(BRANCH_ID)REFERENCES BRANCH(BRANCH_ID));
CREATE TABLE CUSTMOER(CUSTMOER_ID NUMBER(5),C_NAME VARCHAR(10),C_ADDRESS VARCHAR(20),DOB DATE,GENDGER VARCHAR(1),MAIL VARCHAR(50),PINCODE NUMBER(6),PHONE_NO NUMBER(10),BRANCH_ID NUMBER(5),FOREIGN KEY(BRANCH_ID)REFERENCES BRANCH(BRANCH_ID));
CREATE TABLE ACCOUNT(ACCOUNT_ID NUMBER(5)PRIMARY KEY,ACCOUNT_NO NUMBER(10),ACCOUNT_TYPE VARCHAR(10),ACCOUNT_BALANCE NUMBER(10),INTEREST_RATE NUMBER(5),ACCOUNT_STATUS VARCHAR(10),ACC_OPENINNG_DATE DATE,CUSTMOER_ID NUMBER(5),FOREIGN KEY(CUSTMOER_ID)REFERENCES CUSTMOER(CUSTMOER_ID),BRANCH_ID NUMBER(5),FOREIGN KEY(BRANCH_ID)REFERENCES BRANCH(BRANCH_ID));
create table ATM(ATM_ID NUMBER(12)PRIMARY KEY,LOCATION VARCHar(20),CASH NUMBER(10),MAINTENANCE_DATE DATE,STATUS VARCHAR(10),BRANCH_ID NUMBER(5),FOREIGN KEY(BRANCH_ID)REFERENCES BRANCH(BRANCH_ID));
CREATE TABLE LOAN(LOAN_ID NUMBER(10)PRIMARY KEY,AMMOUNT NUMBER(10),LOAN_TYPE VARCHAR(10),INTEREST_REST NUMBER(5),LOAN_TEAM VARCHAR(10),CUSTMOER_ID NUMBER(5),FOREIGN KEY(CUSTMOER_ID)REFERENCES CUSTMOER(CUSTMOER_ID),BRANCH_ID NUMBER(5),FOREIGN KEY(BRANCH_ID)REFERENCES BRANCH(BRANCH_ID));
CREATE TABLE CARDS(CARD_ID NUMBER(5)PRIMARY KEY,ACCOUNT_ID NUMBER(5),FOREIGN KEY(ACCOUNT_ID)REFERENCES ACCOUNT(ACCOUNT_ID),EXPIRY_DATE DATE,CARD_TYPE VARCHAR(10),CARD_NUMBER NUMBER(12),CARD_STATUS VARCHAR(10));
CREATE TABLE TRANSACTION(T_ID NUMBER(5),T_TIME DATE,AMMOUNT_ID NUMBER(5),T_TYPE VARCHAR(10),T_DATE DATE,ACCOUNT_ID NUMBER(5),FOREIGN KEY(ACCOUNT_ID)REFERENCES ACCOUNT(ACCOUNT_ID),CUSTMOER_ID NUMBER(5),FOREIGN KEY(CUSTMOER_ID)REFERENCES CUSTMOER(CUSTMOER_ID),BRANCH_ID NUMBER(5),FOREIGN KEY(BRANCH_ID)REFERENCES BRANCH(BRANCH_ID),BANK_ID NUMBER(5),FOREIGN KEY(BANK_ID)REFERENCES BANK(BANK_ID),ATM_ID NUMBER(12),FOREIGN KEY(ATM_ID)REFERENCES ATM(ATM_ID),EMPLOYEE_ID NUMBER(5),FOREIGN KEY(EMPLOYEE_ID)REFERENCES EMPLOYEE(EMPLOYEE_ID),CARD_ID NUMBER(5),FOREIGN KEY(CARD_ID)REFERENCES CARDS(CARD_ID));
